#import <Foundation/Foundation.h>
#import <CoreWLAN/CoreWLAN.h>
int main(int argc,const char **argv) { @autoreleasepool { if(argc<2)return 2; NSString *name=[NSString stringWithUTF8String:argv[1]];NSError *err=nil;NSSet *nets=[[[CWWiFiClient sharedWiFiClient] interface] scanForNetworksWithName:name error:&err];for(CWNetwork *n in nets)printf("Open security: %d; WPA2 personal: %d; RSSI: %ld\n",[n supportsSecurity:kCWSecurityNone],[n supportsSecurity:kCWSecurityWPA2Personal],(long)n.rssiValue);printf("Targeted scan %s: %lu results; error: %s\n",argv[1],(unsigned long)nets.count,err?err.localizedDescription.UTF8String:"none"); if(argc==3 && strcmp(argv[2],"--join")==0) { if(nets.count!=1)return 3; err=nil; BOOL ok=[[[CWWiFiClient sharedWiFiClient] interface] associateToNetwork:[nets anyObject] password:nil error:&err]; printf("Association: %s; %s\n",ok?"success":"failed",err?err.localizedDescription.UTF8String:"none"); return ok?0:4; } } }
